{
  "title": "部落的考验",
  "scene": "你来到了一个古老的部落，部落的首领告诉你，为了证明你的勇气，你必须通过一个考验。考验是在部落后面的神秘森林中找到一只叫做‘九尾狐’的异兽，并带回来它的毛发。首领给了你一把木剑和一张地图。地图上标着一个奇怪的符号，首领说这是找到九尾狐的关键。但是森林里有很多其他的异兽，看起来都很危险。首领还说，森林深处有一个古老的祭坛，祭坛上有一个神秘的神器，可以保护你不受伤害。你会怎么行动？",
  "goal": "找到九尾狐并带回它的毛发",
  "clue": "地图上的奇怪符号实际上指向了祭坛的位置，而九尾狐常常在祭坛附近出现。",
  "choices": [
    {
      "id": "A",
      "text": "直接进森林找九尾狐",
      "outcome": "森林里有很多危险的异兽，你很快就被一只凶猛的山兽追赶，虽然没有受伤，但也没找到九尾狐。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "先去祭坛找神器",
      "outcome": "你找到了祭坛和神器，神器发出温暖的光芒，保护了你。在祭坛附近，你发现了安静休憩的九尾狐，顺利带回了它的毛发。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "在森林边缘观察",
      "outcome": "你在森林边缘观察了很久，虽然看到了一些异兽，但没有发现九尾狐的踪迹。时间流逝，你的勇气受到了质疑。",
      "result": "partial",
      "next": "retry"
    }
  ]
}
